insert into activities (name, category, icon, description, location_text, indoor_outdoor, physical_effort, walking_distance_m, has_stairs, has_seating, has_toilets, has_parking, public_transport_access, typical_cost_low, typical_cost_high, typical_duration_mins, ai_summary, ai_summary_source, ai_summary_confidence, ai_summary_review_status)
select * from (values
  ('WA Museum Story Tour', 'History & Culture', '🏛️', 'A gently paced highlights tour with lifts, seating, and time to explore the stories that interest you.', 'WA Museum Boola Bardip, Perth', 'indoor', 1::numeric, 350::numeric, false, true, true, true, 'good', 10::numeric, 15::numeric, 105::numeric, 'A comfortable museum visit with seating, accessible facilities, and a flexible pace.', 'manual', 0.95::numeric, 'approved'),
  ('Matinee at His Majesty''s', 'Music & Shows', '🎭', 'An afternoon performance in a historic theatre with reserved seating and nearby parking.', 'His Majesty''s Theatre, Perth', 'indoor', 1::numeric, 180::numeric, true, true, true, true, 'good', 30::numeric, 55::numeric, 150::numeric, 'A seated cultural afternoon with easy transport and a comfortable interval.', 'manual', 0.9::numeric, 'approved'),
  ('Subiaco Farmers Market', 'Markets & Shopping', '🧺', 'A friendly weekend market with local produce, shaded rest areas, and plenty of cafe stops.', 'Subiaco Primary School, Perth', 'outdoor', 2::numeric, 600::numeric, false, true, true, true, 'good', 5::numeric, 25::numeric, 90::numeric, 'A relaxed local market with seating, refreshments, and flexible walking.', 'manual', 0.9::numeric, 'approved')
) as seed(name, category, icon, description, location_text, indoor_outdoor, physical_effort, walking_distance_m, has_stairs, has_seating, has_toilets, has_parking, public_transport_access, typical_cost_low, typical_cost_high, typical_duration_mins, ai_summary, ai_summary_source, ai_summary_confidence, ai_summary_review_status)
where not exists (select 1 from activities where activities.name = seed.name);
